import {parseHtml,serializeHtml,completeHtml,formatHtml} from './html.js';
import {completeXaml} from './xaml-language.js';
import {serializeXaml,parseXaml} from './xaml.js';
import {propertyGroups} from './registry.js';
const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
export class XamlEditor {
  constructor(host,{registry,onApply,onSelection}){this.registry=registry;this.onApply=onApply;this.onSelection=onSelection;this.host=host;this.dirty=false;this.searchIndex=0;this.editHistory=[];this.editFuture=[];this.lastText='';this.syncedText='';
    host.innerHTML=`<div class="editor-find" hidden><input aria-label="Find in XAML" placeholder="Find in XAML"><input aria-label="Replace in XAML" placeholder="Replace with"><button data-find="next">Next</button><button data-find="replace">Replace</button><button data-find="all">All</button><button data-find="close" aria-label="Close find">×</button></div><div class="editor-body"><div class="line-numbers" aria-hidden="true"></div><div class="code-viewport"><pre class="code-highlight" aria-hidden="true"></pre><textarea class="code-input" aria-label="XAML code editor" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" wrap="off"></textarea><div class="completions" role="listbox" hidden></div></div></div><div class="editor-status"><span class="code-message">XAML</span><span class="code-position">Ln 1, Col 1</span></div>`;
    this.input=host.querySelector('textarea');this.highlight=host.querySelector('pre');this.lines=host.querySelector('.line-numbers');this.completions=host.querySelector('.completions');this.message=host.querySelector('.code-message');this.position=host.querySelector('.code-position');
    this.input.addEventListener('input',e=>{this.changed({defer:true});if(!e.isComposing&&this.input.value[this.input.selectionStart-1]?.match(/[.<{=\w]/))this.complete();});this.input.addEventListener('scroll',()=>{this.highlight.scrollTop=this.input.scrollTop;this.highlight.scrollLeft=this.input.scrollLeft;this.lines.scrollTop=this.input.scrollTop;this.hideCompletions();});this.input.addEventListener('click',()=>{this.hideCompletions();this.cursor();});this.input.addEventListener('keyup',()=>this.cursor());this.input.addEventListener('keydown',e=>this.keydown(e));
    host.querySelector('.editor-find').addEventListener('click',e=>{const action=e.target.dataset.find;if(!action)return;if(action==='close'){host.querySelector('.editor-find').hidden=true;return;}const [a,b]=host.querySelectorAll('.editor-find input');if(!a.value)return;const value=this.input.value;if(action==='all'){this.input.value=value.split(a.value).join(b.value);this.changed();return;}if(action==='replace'&&value.slice(this.input.selectionStart,this.input.selectionEnd)===a.value){this.input.setRangeText(b.value,this.input.selectionStart,this.input.selectionEnd,'end');this.changed();}const at=this.input.value.indexOf(a.value,this.input.selectionEnd);const start=at<0?this.input.value.indexOf(a.value):at;if(start>=0){this.input.focus();this.input.setSelectionRange(start,start+a.value.length);this.reveal(start);}else this.message.textContent='No matches';});
  }
  setLanguage(language='XAML'){this.language=language;this.input.setAttribute('aria-label',language+' code editor');this.host.querySelectorAll('.editor-find input').forEach((el,i)=>{el.setAttribute('aria-label',(i?'Replace in ':'Find in ')+language);if(!i)el.placeholder='Find in '+language;});}
  changed({defer=false}={}){const value=this.input.value;if(value!==this.lastText){this.editHistory.push(this.lastText);while(this.editHistory.length>60||(this.editHistory.length>1&&this.editHistory.reduce((n,v)=>n+v.length,0)>8000000))this.editHistory.shift();this.editFuture=[];this.lastText=value;}this.hideCompletions();this.dirty=value!==this.syncedText;this.paint();clearTimeout(this.timer);if(defer)this.timer=setTimeout(()=>this.validate(),350);else this.validate();}
  undoBuffer(){if(!this.editHistory.length)return false;this.editFuture.push(this.input.value);return this.restoreBuffer(this.editHistory.pop());}
  redoBuffer(){if(!this.editFuture.length)return false;this.editHistory.push(this.input.value);return this.restoreBuffer(this.editFuture.pop());}
  restoreBuffer(value){this.lastText=value;this.input.value=value;this.input.setSelectionRange(value.length,value.length);this.changed();return true;}

  setValue(value,{force=false}={}){if(this.dirty&&!force)return false;this.hideCompletions();const pos=this.input.selectionStart,scroll=this.input.scrollTop;if(value!==this.lastText){this.editHistory=[];this.editFuture=[];}this.syncedText=value;this.lastText=value;this.input.value=value;this.input.setSelectionRange(Math.min(pos,value.length),Math.min(pos,value.length));this.input.scrollTop=scroll;this.dirty=false;this.paint();this.message.textContent=(this.language||'XAML')+' · synchronized';return true;}
  paint(){const v=this.input.value;const parts=v.split(/(<!--[^]*?-->|"[^"\n]*"|'[^'\n]*'|<\/?[\w:.-]+|\/?>|[\w:.-]+(?=\s*=))/g);this.highlight.innerHTML=parts.map(t=>t.startsWith('<!--')?`<span class="syntax-comment">${esc(t)}</span>`:t[0]==='"'||t[0]==="'"?`<span class="syntax-string">${esc(t)}</span>`:t[0]==='<'||t==='>'||t==='/>'?`<span class="syntax-tag">${esc(t)}</span>`:/^[\w:.-]+$/.test(t)?`<span class="syntax-attr">${esc(t)}</span>`:esc(t)).join('')+'\n';this.lines.textContent=Array.from({length:v.split('\n').length},(_,i)=>i+1).join('\n');this.cursor();}
  cursor(){const before=this.input.value.slice(0,this.input.selectionStart);this.position.textContent=`Ln ${before.split('\n').length}, Col ${before.length-before.lastIndexOf('\n')}`;}
  validate(){try{(this.language==='HTML'?parseHtml:parseXaml)(this.input.value);this.message.textContent=this.dirty?'Valid '+(this.language||'XAML')+' · Apply to canvas (Ctrl+Enter)':(this.language||'XAML')+' · synchronized';this.message.classList.remove('error');return true;}catch(e){this.message.textContent=`${e.line||1}:${e.column||1} ${e.message}`;this.message.classList.add('error');return false;}}
  apply(){if(!this.validate())return false;try{this.onApply(this.input.value);this.syncedText=this.input.value;this.dirty=false;this.message.textContent=(this.language||'XAML')+' · synchronized';return true;}catch(error){this.message.textContent=error.message;this.message.classList.add('error');this.dirty=true;return false;}}
  format(){try{this.input.value=this.language==='HTML'?formatHtml(this.input.value):serializeXaml(parseXaml(this.input.value));this.changed();}catch(e){this.validate();}}
  find(){this.host.querySelector('.editor-find').hidden=false;this.host.querySelector('.editor-find input').focus();}
  reveal(index){const line=this.input.value.slice(0,index).split('\n').length;const measured=typeof getComputedStyle==='function'?parseFloat(getComputedStyle(this.input).lineHeight):NaN;this.input.scrollTop=Math.max(0,(line-4)*(Number.isFinite(measured)?measured:21));this.highlight.scrollTop=this.input.scrollTop;this.lines.scrollTop=this.input.scrollTop;}
  revealName(name){const at=this.input.value.indexOf(`="${name}"`);if(at>=0){this.input.setSelectionRange(at+2,at+2+name.length);this.reveal(at);this.cursor();}}
  complete(){const source=this.input.value,caret=this.input.selectionStart;const context=this.getLanguageContext?.()||{};const items=(this.language==='HTML'?completeHtml(this.input.value,this.input.selectionStart):completeXaml(this.input.value,this.input.selectionStart,{registry:this.registry,...context})).slice(0,60);if(!items.length){this.hideCompletions();return;}this.completions.replaceChildren();this.completions.hidden=false;for(const [index,entry] of items.entries()){const item=document.createElement('button');item.role='option';item.title=entry.detail;const label=document.createElement('span');label.textContent=entry.label;const detail=document.createElement('small');detail.textContent=entry.detail;item.append(label,detail);item.classList.toggle('active',index===0);item.onmousedown=e=>{e.preventDefault();if(this.input.value!==source||this.input.selectionStart!==caret){this.hideCompletions();return;}this.input.setRangeText(entry.insertText,entry.start,entry.end,'end');if(entry.caretOffset!==undefined)this.input.setSelectionRange(entry.start+entry.caretOffset,entry.start+entry.caretOffset);this.changed();this.hideCompletions();this.input.focus();};this.completions.append(item);}this.completionIndex=0;}
  hideCompletions(){this.completions.hidden=true;}
  keydown(e){if(e.isComposing)return;if(['ArrowLeft','ArrowRight','Home','End','PageUp','PageDown'].includes(e.key))this.hideCompletions();const mod=e.ctrlKey||e.metaKey;if(mod&&['z','y'].includes(e.key.toLowerCase())){e.preventDefault();e.stopPropagation();if(e.shiftKey||e.key.toLowerCase()==='y')this.redoBuffer();else this.undoBuffer();return;}if(mod&&e.key==='Enter'){e.preventDefault();this.apply();return;}if(mod&&e.code==='Space'){e.preventDefault();this.complete();return;}if(mod&&e.key.toLowerCase()==='f'){e.preventDefault();this.find();return;}if(e.shiftKey&&e.altKey&&e.key.toLowerCase()==='f'){e.preventDefault();this.format();return;}if(e.key==='Escape')this.hideCompletions();
    if(!this.completions.hidden&&['ArrowDown','ArrowUp','Enter','Tab'].includes(e.key)){e.preventDefault();const items=[...this.completions.children];if(e.key==='Enter'||e.key==='Tab'){items[this.completionIndex].dispatchEvent(new MouseEvent('mousedown',{bubbles:true}));return;}this.completionIndex=(this.completionIndex+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items.forEach((n,i)=>n.classList.toggle('active',i===this.completionIndex));return;}
    if(e.key==='Tab'){e.preventDefault();const a=this.input.selectionStart,b=this.input.selectionEnd;if(a!==b){const start=this.input.value.lastIndexOf('\n',a-1)+1,text=this.input.value.slice(start,b),out=e.shiftKey?text.replace(/^ {1,4}/gm,''):text.replace(/^/gm,'    ');this.input.setRangeText(out,start,b,'select');}else this.input.setRangeText('    ',a,b,'end');this.changed();}
    if(e.key==='Enter'){e.preventDefault();const a=this.input.selectionStart,before=this.input.value.slice(0,a),indent=before.split('\n').at(-1).match(/^\s*/)[0];const extra=/<[^/!?][^>]*>$/.test(before)&&!before.endsWith('/>')?'    ':'';this.input.setRangeText('\n'+indent+extra,a,this.input.selectionEnd,'end');this.changed();}
    if(mod&&e.key==='/'){e.preventDefault();const a=this.input.selectionStart,b=this.input.selectionEnd;const start=this.input.value.lastIndexOf('\n',a-1)+1,end=this.input.value.indexOf('\n',b);const text=this.input.value.slice(start,end<0?this.input.value.length:end);const out=text.trim().startsWith('<!--')?text.replace('<!--','').replace('-->','').trim():`<!-- ${text} -->`;this.input.setRangeText(out,start,end<0?this.input.value.length:end,'select');this.changed();}
  }
}
